package com.example.starter.calibration.domain;

/**
 * 传感器类型。
 */
public enum SensorType {
    /** 相机：校验内参焦距为正。 */
    CAMERA,
    /** 激光雷达：仅校验外参。 */
    LIDAR,
    /** 毫米波雷达：仅校验外参。 */
    RADAR,
    /** 惯性测量单元：使用 IMU 专用参数字段。 */
    IMU
}

package com.example.starter.calibration.domain;

/**
 * 标定版本审批与发布状态。
 */
public enum CalibrationStatus {
    /** 草稿：刚创建、未通过校验或未审批，不参与解析。 */
    DRAFT,
    /** 已批准：校验通过并完成审批，可用于灰度或全量生效。 */
    APPROVED,
    /** 灰度中：仅对灰度发布单指定车辆集合生效。 */
    IN_CANARY,
    /** 已生效：全量车辆可解析的常规版本。 */
    EFFECTIVE,
    /** 已回滚：灰度终止后的版本，不再参与解析。 */
    ROLLED_BACK
}

package com.example.starter.calibration.domain;

/**
 * 灰度发布单状态。
 */
public enum ReleaseStatus {
    /** 已发布：灰度车辆切换到新版本。 */
    ROLLED_OUT,
    /** 已回滚：灰度车辆恢复到各自发布前版本。 */
    ROLLED_BACK
}

package com.example.starter.calibration.web;

import org.springframework.http.HttpStatus;

/**
 * 标定服务 API 错误基类，携带 HTTP 状态码与错误信息。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;

    public ApiException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus getStatus() {
        return status;
    }

    /** 标定内容或状态机校验失败：422。 */
    public static class Unprocessable extends ApiException {
        public Unprocessable(String message) {
            super(HttpStatus.UNPROCESSABLE_ENTITY, message);
        }
    }

    /** 生效范围冲突、并发冲突等：409。 */
    public static class Conflict extends ApiException {
        public Conflict(String message) {
            super(HttpStatus.CONFLICT, message);
        }
    }

    /** 资源不存在：404。 */
    public static class NotFound extends ApiException {
        public NotFound(String message) {
            super(HttpStatus.NOT_FOUND, message);
        }
    }
}

package com.example.starter.calibration.web;

import java.time.OffsetDateTime;
import java.util.Map;

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * 将业务异常统一转换为错误响应体。
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<Map<String, Object>> handleApi(ApiException ex) {
        return ResponseEntity.status(ex.getStatus()).body(Map.of(
                "timestamp", OffsetDateTime.now().toString(),
                "status", ex.getStatus().value(),
                "error", ex.getStatus().getReasonPhrase(),
                "message", ex.getMessage()));
    }
}

