package com.example.starter.calibration.domain.payload;

import java.util.List;

/**
 * 相机内参。
 *
 * @param fx                 x 方向焦距，单位像素，必须为正
 * @param fy                 y 方向焦距，单位像素，必须为正
 * @param cx                 主点 x 坐标，单位像素
 * @param cy                 主点 y 坐标，单位像素
 * @param distortionCoeffs   畸变系数（可为空表示不考虑畸变），单位 1
 */
public record CameraIntrinsics(
        double fx,
        double fy,
        double cx,
        double cy,
        List<Double> distortionCoeffs) {
}

package com.example.starter.calibration.domain.payload;

import java.util.List;

/**
 * 相机/LiDAR/Radar 相对车体坐标系的外参。
 *
 * @param rotation    3x3 旋转矩阵（无量纲），在配置容差内正交且行列式近似 +1
 * @param translation 平移向量 [x,y,z]，单位米
 */
public record Extrinsics(
        List<List<Double>> rotation,
        List<Double> translation) {
}

package com.example.starter.calibration.domain.payload;

import java.util.List;

/**
 * IMU 参数。
 *
 * @param accelerometerBias        加速度计零偏 [x,y,z]，单位 m/s^2
 * @param gyroscopeBias            陀螺仪零偏 [x,y,z]，单位 rad/s
 * @param accelerometerNoiseDensity 加速度计噪声密度，单位 ug/sqrt(Hz) 对应数值，必须非负
 * @param gyroscopeNoiseDensity     陀螺仪噪声密度，单位 rad/s/sqrt(Hz)，必须非负
 */
public record ImuParameters(
        List<Double> accelerometerBias,
        List<Double> gyroscopeBias,
        double accelerometerNoiseDensity,
        double gyroscopeNoiseDensity) {
}

package com.example.starter.calibration.domain.payload;

/**
 * 一份标定参数的完整内容，按传感器类型使用对应字段。
 *
 * @param cameraIntrinsics 相机内参，仅 CAMERA 必填
 * @param extrinsics       外参，CAMERA/LIDAR/RADAR 校验；IMU 可为空
 * @param imu              IMU 参数，仅 IMU 必填
 */
public record CalibrationPayload(
        CameraIntrinsics cameraIntrinsics,
        Extrinsics extrinsics,
        ImuParameters imu) {
}

